#!/bin/bash
# Task 172-w17-t1carry -- meshsim sim/ WORKER17 (branch sim-w17 eb09b0f; sim/ref, precompiled).
# ref's memory at every segment's start: T1Carry through all 128 segments of evm-zone-29 and cyclone-29 (two JVMs, not timing).
# Per segment the snapshot's sha256 and filesScan; the landings' sha256 of segments 0, 1, 10, 126, 127; segment 10 against W13's dumps.
# From an embedded kit. Writes only results/172-w17-t1carry/. Scratch in /tmp, removed first and at the end; inputs only read.
set -u
cd "$(dirname "$0")/.."
REPO=$PWD; RES=$REPO/results/172-w17-t1carry; mkdir -p "$RES"
W=/tmp/w17-172-w17-t1carry; rm -rf "$W"; mkdir -p "$W"
sed -n '/^__KIT_BEGIN__$/,/^__KIT_END__$/p' "$0" | sed '1d;$d' | base64 -d > "$W/kit.tgz" || exit 2
GOT=$(sha256sum "$W/kit.tgz" | cut -d' ' -f1); echo "kit sha256 $GOT"
[ "$GOT" = "b91b0e5a7c0e448e93c0cf7811c99e198b64d7feaaa99b7afa74ba4325134730" ] || { echo "kit sha256 mismatch (want b91b0e5a7c0e448e93c0cf7811c99e198b64d7feaaa99b7afa74ba4325134730)"; exit 2; }
tar -xzf "$W/kit.tgz" -C "$W" || exit 2
(cd "$W/kit" && sha256sum -c --quiet HASHES) || { echo "kit files differ from HASHES"; exit 2; }
KR=$W/kit/run; KC=$W/kit/classes:$W/kit/gold; KT=$W/kit/tables/replayer; KS=$W/kit/sim
DATA=${T1_DATA:-$HOME/data}; [ -d "$DATA/w26-jumpmap" ] || DATA=$REPO/data
D9=$DATA/w9-deliveries; D26=$DATA/w26-jumpmap
FAIL=0
sec() { echo; echo "==== $*  [$(date +%T)]"; }
verdict() { echo "VERDICT $1: $2"; [ "$2" = PASS ] || FAIL=1; }
# program : the delivery manifest's SHA-256 : WORKER26's manifest.sha256's SHA-256 (as 110u)
declare -A S9=([evm-zone-29]=7142e894c80a0c9d491f21c852a942885e0abd97cfe6aefd0101d716824e138f [cyclone-29]=f8a0622e144a944c51386b5b36f81101dcdeb16e5a8d950c1e9ca0e3097f8982)
declare -A S26=([evm-zone-29]=57dc0ffe7574ab3e11f79f8414501bd1ceb2fd75faab0b03f3b4a6c2c61cad2d [cyclone-29]=ace78f61efbb9c0e418a0b1d7f54a79f6e299b7ff45ad7f09537b11961b95fba)
checkin() {
  local P=$1 A B
  A=$(sha256sum "$D9/$P.manifest.json" 2>/dev/null | cut -d' ' -f1); B=$(sha256sum "$D26/$P/manifest.sha256" 2>/dev/null | cut -d' ' -f1)
  [ "$A" = "${S9[$P]}" ] && [ "$(cat "$D9/$P.COMPLETE" 2>/dev/null)" = "$A" ] || { echo "$P: the delivery isn't complete or differs"; return 1; }
  [ "$B" = "${S26[$P]}" ] && [ "$(cat "$D26/$P.COMPLETE" 2>/dev/null)" = "$B" ] || { echo "$P: WORKER26's inputs aren't complete or differ"; return 1; }
  (cd "$D26/$P" && sha256sum -c --quiet manifest.sha256) || { echo "$P: WORKER26's files differ from their manifest"; return 1; }
  echo "$P: inputs checked (delivery $A, w26 $B)"
}
START=$(date +%s)
{
sec "machine (D21)"; . "$KS/tools/machine.sh" "${QUEST_P_CPUS:-}" "${QUEST_E_CPUS:-}"; machine_record "$RES/machine.txt"; uptime
cat "$W/kit/VERSION"; java -version 2>&1 | head -1; echo "persistent data: $DATA"
# t1carry-body.sh (WORKER17, the owner's Q1): ref's memory at every segment's start, T1's carry through all 128
# segments of evm-zone-29 and cyclone-29 (T1Carry; two JVMs in parallel; not timing). Per segment: nextFree, pages,
# filesScan and the sha256 of the snapshot's stream (W13's M3FILES1, uncompressed); the landings' sha256 (M3SRAM01,
# uncompressed) of segments 0, 1, 10, 126, 127. Checks: T1's end state against every next frame 2 and seg/NNN.pages
# against the update lists (T1Carry's own); segment 10's start and landings equal W13's snapshot and sram dumps
# ($DATA/w13-golden-m3, checked first against golden-m3/HASHES); 128 starts each.
sec "inputs"
OKIN=1; for P in evm-zone-29 cyclone-29; do checkin $P || OKIN=0; done
G=$DATA/w13-golden-m3
(cd "$G" && grep -E ' (evm|cyclone)\.(files|sram)\.gz$' "$W/kit/golden-m3/HASHES" | sha256sum -c) || OKIN=0
[ $OKIN = 1 ] && verdict inputs PASS || verdict inputs FAIL
if [ $OKIN = 1 ]; then
  cd "$KR"
  sec "T1's carry, both workloads (two JVMs)"
  PIDS=""
  for P in evm-zone-29 cyclone-29; do
    S=${P%%-*}
    java -Xmx${T1_HEAP:-6g} -Dreplay.tables=$KT -cp $KC T1Carry $P --w26 $D26/$P sram=0,1,10,126,127 > $RES/$S.t1carry.txt 2>&1 & PIDS="$PIDS $!:$S"
  done
  for X in $PIDS; do wait ${X%%:*}; R=$?; S=${X#*:}; echo "$S: exit $R"; grep -v '^start ' "$RES/$S.t1carry.txt"; [ $R = 0 ] && verdict "t1carry-$S" PASS || verdict "t1carry-$S" FAIL; done
  for S in evm cyclone; do
    N=$(grep -c '^start ' $RES/$S.t1carry.txt); echo "$S: $N starts"; [ "$N" = 128 ] && verdict "$S-128-starts" PASS || verdict "$S-128-starts" FAIL
    A=$(awk '$1 == "start" && $2 == 10 {print $10}' $RES/$S.t1carry.txt); B=$(zcat $G/$S.files.gz | sha256sum | cut -d' ' -f1)
    echo "$S segment 10 start: T1Carry $A, W13's snapshot $B"; [ -n "$A" ] && [ "$A" = "$B" ] && verdict "$S-start10-equals-w13" PASS || verdict "$S-start10-equals-w13" FAIL
    A=$(awk '$1 == "sram" && $2 == 10 {print $4}' $RES/$S.t1carry.txt); B=$(zcat $G/$S.sram.gz | sha256sum | cut -d' ' -f1)
    echo "$S segment 10 landings: T1Carry $A, W13's sram $B"; [ -n "$A" ] && [ "$A" = "$B" ] && verdict "$S-sram10-equals-w13" PASS || verdict "$S-sram10-equals-w13" FAIL
    grep -E '^(start|sram) ' $RES/$S.t1carry.txt > $RES/$S.starts
  done
fi
sec "done in $(($(date +%s) - START)) s"
} 2>&1 | tee "$RES/run.log"
grep '^VERDICT' "$RES/run.log" > "$RES/VERDICTS.txt"
rm -rf "$W"
grep -q ': FAIL$' "$RES/VERDICTS.txt" && exit 1
exit 0
